Matching Ayahs
- = Аліф, Лям, Мім. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Яны на прамым шляху ад свайго Госпада, і яны — тыя, хто дасягнуў поспеху. 2:5; 31:5
- = О, сыны Ізраіля! Памятайце ласку Маю, якую Я аказаў вам, і тое, што Я адрозніў вас над сусветамі (народамі). 2:47; 2:122
- = Гэта народ, які ўжо прайшоў. Яму — тое, што ён набыў, і вам — тое, што вы набылі. І вас не спытаюць аб тым, што яны рабілі. 2:134; 2:141
- = Вечна там застаючыся. Не будзе ім палёгкі ў пакаранні, і не будуць яны адтэрмінаваны. 2:162; 3:88
- = Акрамя тых, хто пакаецца пасля гэтага і выправіцца. Бо, сапраўды, Аллах — Даруючы, Міласэрны. 3:89; 24:5
- = А тыя, хто не ўвераваў і адкінуў Нашы знамёны — яны жыхары Пекла. 5:10; 5:86
- = І якое б знамёна з знамёнаў свайго Госпада ні прыходзіла да іх, яны адварочваюцца ад яго. 6:4; 36:46
- = І сапраўды, насміхаліся з пасланцаў да цябе, але тых, хто здзекваўся, спасцігла тое, з чаго яны насміхаліся. 6:10; 21:41
- = Скажі: "Я баюся, калі не паслухаюся свайго Госпада, пакарання Вялікага дня." 6:15; 39:13
- = Дык вось, землятрус уразіў іх, і яны апынуліся ў сваіх дамах паваленымі. 7:78; 7:91
- = І ён кінуў свой посах, і вось — ён змяёй відавочнай стаў. 7:107; 26:32
- = І выцягнуў ён сваю руку, і вось — яна белай стала для тых, хто глядзеў. 7:108; 26:33
- = Яны сказалі: "Мы ўверавалі ў Госпада сусветаў." 7:121; 26:47
- = Госпада Мусы і Гаруна. 7:122; 26:48
- = І Я дам ім адтэрміноўку. Сапраўды, мая хітрасць — моцная. 7:183; 68:45
- = Ён Той, Хто паслаў Свайго Пасланца з прамым шляхам і рэлігіяй ісціны, каб узвысіць яе над усімі рэлігіямі, нават калі гэта непрыемна шматбожнікам. 9:33; 61:9
- = О, Прарок! Барацьбі з няверуючымі і крывадушнікамі і будзь суровым да іх. Іх прытулак — Пекла, і кепскі гэта канец! 9:73; 66:9
- = І яны кажуць: "Калі ж гэта абяцанне, калі вы кажаце праўду?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = І Мы сапраўды паслалі Мусу з Нашымі знамёнамі і яўнай уладай. 11:96; 40:23
- = І Мы сапраўды далі Мусе Пісанне, але вакол яго ўзніклі рознагалоссі. І калі б не слова, якое ўжо было ад твайго Госпада, то між імі было б вырашана. І яны, сапраўды, у несупынным сумненні адносна яго. 11:110; 41:45
- = Гэта не цяжка для Аллаха. 14:20; 35:17
- = І калі Я надам яму форму і ўдыхну ў яго ад Майго духа, то ўпадзеце перад ім у паклоне. 15:29; 38:72
- = І ўсе анёлы пакланіліся — усе цалкам. 15:30; 38:73
- = (Аллах) сказаў: "Выйдзі ж адтуль, бо, сапраўды, ты прагнаны." 15:34; 38:77
