- Аллах не будзе караць вас за пустаслоўе ў вашых клятвах, але Ён пакарае вас за тое. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- Літасць, яны цешацца з яе, а калі іх кране зло за тое, што паслалі іх рукі. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- Сады, дзе пад імі цякуць рэкі, дзе яны будуць вечна, і выдатная ўзнагарода тых, хто працуе. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- Аллах і Ён ведае тое, што ў нябёсах і што на зямлі, і Аллах. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- Слухайцеся Аллаха і слухайцеся Пасланца; а калі адвернецеся, то на ім (ляжыць адказнасць). (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- Ім узнагарода іх у іх Госпада, і няма страху для іх, і яны. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- І яны сказалі: "Калі мы станем касцямі і прахам, няўжо мы будзем уваскрэшаны новым стварэннем?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- І яны не знойдуць сабе, акрамя Аллаха, ні абаронцы, ні памочніка. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
