- Хто робіць дабрыню, мужчына ці жанчына, і ён веруючы. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- Тыя, хто адводзіць ад шляху Аллаха і хоча яго скрывіць, і яны ў будучым жыцці. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- Ешце, дзе хочаце, але не набліжайцеся да гэтага дрэва, каб не стаць крыўдзіцелямі. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- Скажы: "О народ мой! Дзейнічайце па-свойму, я таксама буду дзейнічаць, і вы даведаецеся." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- Сапраўды, тыя, хто пацярпеў страты — хто страціў сябе і свае сем'і ў Дзень Уваскрэсення, ці ж не. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- Хто ідзе прамым шляхам, той ідзе на карысць сабе, а хто збіваецца, той збіваецца на шкоду сабе, і. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
