- Вечна там, не будзе палёгкі ім у пакаранні, і не будзе ім адтэрміноўкі. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
