- І не абрабавайце людзей у іх маёмасці, і не чыніце беззаконня на зямлі. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- І мір яму ў дзень, калі ён нарадзіўся, і ў дзень, калі ён памрэ, і ў дзень, калі ён будзе ўваскрэшаны жывым. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- О народ мой! Дзейнічайце па-свойму, я таксама буду дзейнічаць, і вы даведаецеся, хто. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
