- Паглядзі, як яны прыводзяць табе прыклады, і самі збіліся з шляху і не могуць знайсці дарогі. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- Скажы: "Я баюся, калі не паслухаюся майго Госпада, пакарання ў Вялікі дзень." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
