- Усё, што на зямлі, і яшчэ столькі ж, каб выкупіць сябе. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- Вазьміце тое, што Мы далі вам, моцна, і памятайце тое, што ў ім, каб вы былі багабаязнымі. (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- Хіба вы чыніце брыдкае, якое не чыніў да вас ніхто з людзей? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- Алаху належыць тое, што ў нябёсах, і тое, што на зямлі, і Аллах быў. (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- Іх здабыткі пацягнулі за сабой пакаранне, і тое, з чаго яны кпілі, аблажыла іх. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- Пасланца з вас, які чытае вам Нашы знамёны, ачышчае вас і навучае вас Пісанню і Мудрасці. (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- З яго біла дванаццаць крыніц; кожны люд ведаў сваё месца для піцця. (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- Толькі здагадка; сапраўды, здагадка не выратуе ад ісціны. (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- Калі я яго завяршу і ўдыхну ў яго ад Майго духу, то ўпадзеце перад ім у зямным паклоне. (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
