- Той, Хто стварыў нябёсы і зямлю, здольны стварыць падобных да іх. (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- Веруючым мужчынам і веруючым жанчынам — сады, дзе пад імі цякуць рэкі, дзе яны будуць вечна. (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
