- І вось Мы сказалі анёлам: "Упадзіце ў паклоне перад Адамам." Яны ўпалі, акрамя Ібліса, які адмовіўся. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَى) 2:34; 20:116
