- Ім пітво з кіпеню і пакутлівае пакаранне за тое, што яны не верылі. (لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْفُرُونَ) 6:70; 10:4
