- Сапраўды, Алах — мой Гасподзь і ваш Гасподзь, дык пакланяйцеся Яму; гэта прамы шлях. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- Валодальца міласці для людзей, але большасць іх не ўдзячныя. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Нябёсы і зямлю і тое, што паміж імі, Мы стварылі толькі дзеля праўды і на вызначаны тэрмін. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Пакінь іх, хай яны пагружаюцца ў марнаты і забаўляюцца, пакуль не сустрэнуць свой дзень, які ім абяцаны. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- Калі яны сустракаюць тых, якія ўверавалі, яны кажуць: "Мы ўверавалі", а калі застаюцца сам-насам. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- Яны выконваюць Тору і Евангелле і тое, што было паслана ім ад іх Госпада. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- Ён ведае тое, што перад імі, і тое, што за імі, а яны не ахопліваюць (гэтага) веданнем. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- Ён Той, Хто стварыў нябёсы і зямлю за шэсць дзён. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- У гэтым сапраўды ёсць знак для вас, калі вы веруеце. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Што перашкодзіла людзям увераваць, калі да іх прыйшоў прамы шлях? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- Яны дадалі Алаху роўных, каб збіць з Яго шляху. Скажы: "Карыстайцеся!" (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- Яны здзівіліся, што да іх прыйшоў засцерагальнік з іх саміх, і няверныя сказалі: "Гэта". (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Сапраўды, твой Гасподзь лепш ведае, хто збіўся з Яго шляху. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Падобны да таго, хто марнуе свой маёмасць на паказ людзям і не веруе ў Алаха. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Дайце з таго, чым Мы вас надзялілі, перш чым наступіць. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- Ён падпарадкаваў вам тое, што ў нябёсах, і тое, што на зямлі. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- Мы ў сумневе адносна таго, да чаго вы нас заклікаеце. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Сапраўды, твой Гасподзь пашырае долю каму пажадае і абмяжоўвае каму пажадае. Сапраўды, Ён. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Гасподзь нябёсаў і зямлі і таго, што паміж імі, калі вы перакананыя. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- Мы ўверавалі ў Алаха і ў тое, што паслана нам, і ў тое, што паслана. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- Тых, хто быў несправядлівы, напаткаў крык, і яны апынуліся ў сваіх дамах паваленымі. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Няма на вас граху ў тым, што яны зробяць адносна сябе. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Гасподзь твой лепш ведае, хто збіўся з Яго шляху, і Ён. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- З духам (адкрыццём) паводле Яго загаду на таго, каго Ён пажадае з Сваіх рабоў. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- Мы далі Ісе, сыну Мар'ям, ясныя знакі і ўмацавалі яго Духам Святым. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- Каб Ён рассудзіў паміж імі ў Дзень Уваскрэсення ў тым, у чым яны разыходзіліся. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- Мы зрабілі яе верх нізам і пралілі на яе камяні з абпаленай гліны. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Для іх аднолькава — засцерагаў ты іх ці не засцерагаў — яны не вераць. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Акрамя людзей, (калі вы праўдзівыя), пажадайце сабе смерці. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Алаху, няма ў вас іншага бога. Хіба вы не ўстрашыцеся? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Ці Мы пакажам табе частку таго, што абяцаем ім, ці забярэм тваё жыццё, — да Нас яны вернуцца. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- Яны сказалі: "Няўжо, калі мы памром і станем прахам і косткамі, мы будзем уваскрэшаны?" (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Міласць у руцэ Алаха, Ён дае яе таму, каму пажадае. Алах. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- Да Ведаючага скрытае і яўнае, і Ён абвесціць вам тое, што вы рабілі. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- О тыя, якія ўверавалі! Узгадайце міласць Алаха да вас, калі. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- Мы пасылалі да цябе толькі мужчын, якім давалі адкрыццё. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- Ён даруе яму ліхія ўчынкі і ўвядзе яго ў сады, дзе пад імі цякуць рэкі. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- Хворы або ў дарозе, — то лік іншых дзён. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- Яны не ідуць за чымсьці, акрамя здагадак, і яны толькі выдумляюць. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Выдатны прыклад для тых, хто спадзяецца на Алаха і на Апошні дзень. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- І Мы стварылі нябёсы і зямлю і тое, што паміж імі, не інакш як па праўдзе. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Укладзі сваю руку ў кішэню, яна з'явіцца белай, без хваробы. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- Ён абірае сваёй міласцю таго, каго пажадае, і Алах — валодальца вялікай міласці. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- Хіба ты не ведаеш, што Алаху належыць улада над нябёсамі і зямлёй? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- Што б вы ні зрабілі добрага для сябе, вы знойдзеце гэта ў Алаха. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- І адкуль бы ты ні выйшаў, звяртай свой твар у бок Забароненай мячэці. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- Тыя, хто жыў да вас, — вы не знойдзеце змены ў законах Алаха. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- Таго, Каму належыць тое, што ў нябёсах і што на зямлі. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- Ні адна жанчына не носіць (цяжар) і не нараджае, акрамя як па Яго веданні. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- Ён падпарадкаваў сонца і месяц, кожны рухаецца да вызначанага тэрміну. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Пад імі цякуць рэкі, дзе яны будуць вечна; гэта ўзнагарода. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- Сказаў ён: "Не, гэта вашыя душы ўявілі вам нейкую справу; цярпенне — прыгожае." (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- То, што ў нябёсах і што на зямлі, і што Алах. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- Які б пасланец ні прыходзіў да іх, яны здзекваліся з яго. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- Яны сказалі: "О Муса! Ці ты кінеш, ці мы будзем тымі, хто кіне?" (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- Ён забірае вас (пасля смерці), і сярод вас ёсць той, каго вяртаюць у самыя нізкія гады, каб. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- Для іх — сады, дзе пад імі цякуць рэкі, дзе яны будуць вечна. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- І Мы зрабілі на іх сэрцах покрывы, каб яны не разумелі гэтага, і ў вушах іх — глухату. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Абяцанне Алаха — праўда, але большасць іх не ведае. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- Гэта за тое, што яны супрацьстаялі Алаху і Яго Пасланцу. А хто супрацьстаіць Алаху. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- І ў той дзень, калі Ён пакліча іх і скажа: "Дзе мае супольнікі, якіх вы ўяўлялі?" (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- Хіба яны не бачылі, што Алах, Які стварыў нябёсы і зямлю, (можа стварыць падобнае)? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (Таго), хто стварыў цябе з праху, потым з кроплі, потым. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- Яны сказалі б: "Госпадзе наш! Чаму Ты не паслаў да нас пасланца, каб мы пайшлі за Тваімі знакамі?" (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Потым да свайго Госпада яны вернуцца, і Ён абвесціць ім тое, што яны рабілі. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- У іх няма ведання пра гэта; яны прытрымліваюцца толькі здагадак. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Мы знайшлі сваіх бацькоў на гэтым шляху, і мы ідзем па іх слядах. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- Тыя, каму было дадзена Пісанне, не разышліся, пакуль не прыйшло да іх (веданне). (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- І калі Ібрахім сказаў: "Госпадзе мой, зрабі гэты горад бяспечным!" (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- Ён даў вам слых, зрок і сэрцы; мала вы ўдзячныя. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- Тыя, якія спрачаюцца пра знакі Алаха без улады, якая прыйшла да іх. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Ідзіце за рэлігіяй Ібрахіма — ханіфа, і не быў ён з многобожнікаў. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- І вось Мы ўратавалі вас ад роду Фіраўна, якія падвяргалі вас горшаму пакаранню. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- Гэта — правільная рэлігія, але большасць людзей не ведае. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- Хіба ты не бачыў, што Алах падпарадкаваў вам тое, што ў. (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Тыя, якія не ўверавалі, сказалі б: "Гэта не што іншае, як відавочнае караўніцтва." (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- Калі ім чытаюць Нашы ясныя знакі, тыя, якія не ўверавалі, кажуць. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Сады вечнасці, дзе пад імі цякуць рэкі, дзе яны будуць вечна. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- Ён робіць, што хоча; сапраўды, Алах над кожнай рэччу магутны. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- Каб Ён дараваў вам грахі і адклаў вас да вызначанага тэрміну. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Няўжо вы хочаце адвярнуць нас ад таго, чаму пакланяліся нашы бацькі? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- Калі Гасподзь твой сказаў анёлам: "Я ствару чалавека з гліны". (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- Ён Той, Хто пасылае ветры як добрую вестку перад Сваёй міласцю. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Скажы: "Хадзіце па зямлі і глядзіце, якім быў канец (грэшнікаў)." (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- У стварэнні нябёсаў і зямлі, у змене ночы і дня (ёсць знакі). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Хто той, хто пазычыць Алаху добры пазык, каб Ён памножыў яго? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Судзі паміж імі па тым, што паслаў Алах, і не ідзі за іх жаданнямі. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- Няўжо яны чакаюць чагосьці іншага, акрамя як прыходу анёлаў або прыходу (загаду) твайго Госпада? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Сапраўды, тыя, якія ўзводзяць на Алаха хлусню, не дасягнуць поспеху. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- Падобныя да роду Фіраўна і тых, хто быў да іх — яны лічылі хлуснёй Нашы знакі. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- І паведамляе добрую вестку веруючым, якія робяць добрыя справы, што ім належыць узнагарода. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Алах пашырае долю каму пажадае з Сваіх рабоў, і абмяжоўвае. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- І вы вернецеся да Ведаючага скрытае і яўнае, і Ён абвесціць вам тое, што вы рабілі. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- І блізкія сваякі — адны з іх бліжэйшыя да іншых у Пісанні Алаха. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — абавязковае (трэба рабіць; грэх пакінуць)
- mustahabb / mandub (مستحب / مندوب) — рэкамендаванае (узнагароджваецца, калі зроблена; не грэх, калі пакінута)
- mubah (مباح) — нейтральнае / дазволенае (ні ўзнагароды, ні грэху)
- makruh (مكروه) — агіднае / непажаданае (не рэкамендуецца, але не грэх, калі зроблена)
- haram (حرام) — забароненае (грэх рабіць)
- halal (حلال, дазволенае / законнае) — уключае як mubah, так і mustahabb — усё, што не забаронена
- Пакланяйцеся толькі Алаху і шукайце Яго дапамогі/падтрымкі. 1:5
- Пакланяйцеся толькі Алаху. 2:21
- Не далучайце да Алаха ніякіх супольнікаў. 2:22
- Алах — Той, Хто даруе (прымае пакаянне), Ён прыняў пакаянне Адама (мір яму). 2:37
- Не змешвайце праўду з хлуснёю і не ўтойвайце праўду. 2:42
- Выконвайце салят (штодзённыя малітвы) і давайце закят (міласціну). 2:43
- Загадвайце дабро іншым толькі пасля таго, як самі будзеце яго прытрымлівацца. 2:44
- Шукайце дапамогі Алаха ва ўсіх вашых справах. 2:45
- Не ўдзельнічайце ў распуце і не распаўсюджвайце яе. 2:60
- Не перашкаджайце людзям наведваць дамы пакланення. 2:114
- Паважайце святасць мячэці. Трымайце вашыя месцы для малітвы чыстымі і ачышчанымі. 2:125
- Памінайце Алаха (малітвай, славослоўем і г.д.), і Ён успомніць вас, і будзьце ўдзячныя Яму. 2:152
- Праяўляйце цярпенне ў нягодах. 2:153
- Не ідзіце па слядах Шайтана (Сатаны), які з'яўляецца адкрытым ворагам. 2:168
- Не ідзіце за кімсьці наўздагад. 2:170
- Захоўвайце і выконвайце ўсе даверы. Выконвайце свае рэлігійныя абавязкі з шчырасцю. Выконвайце вашыя клятвы і запаветы. Выконвайце абяцанні, асабліва тыя, якія вы далі Алаху. Падтрымлівайце тых, хто мае патрэбу, і палягчайце цяжкасці. Пазбягайце здзяйснення грахоў, якія вядуць да страты боскай ласкі. Не дазваляйце гордасці весці вас да несправядлівасці. 2:177
- У кісасе (Законе роўнасці ў пакаранні) для вас — жыццё. 2:179
- Трымайце пост у месяц Рамадан. Выконвайце прадпісаны пост, каб стаць мутакунамі (пабожнымі). 2:183
- Паважайце Каран як найвышэйшую крыніцу кіраўніцтва. 2:185
- Не паядайце маёмасці аднаго аднаго несправядліва і не давайце хабар судздзям (перад тым, як прадстаўляць вашыя справы). 2:188
- Не ўціскайце іншых, словам або дзеяннем. Ніколі не змагайцеся як агрэсар, а толькі ў абарону. 2:190
- Абараняйце сірот. Што тычыцца сірот, дзейнічайце сумленна з іх маёмасцю і не паглынайце іх маёмасць. 2:220
- Кайцеся і шукайце прабачэння Алаха. Не ўступайце ў палавыя зносіны падчас менструальнага перыяду. Захоўвайце чысціню (фізічную і духоўную). 2:222
- Выконвайце вашыя абавязкі перад сям'ёй. 2:233
- Выбірайце лідэраў на аснове іх заслуг. 2:247
- Няма прымусу ў рэлігіі. 2:256
- Выдаткоўвайце маёмасць на міласціну. Будзьце міласэрнымі як маёмасцю, так і часам. 2:261
- Не рабіце міласціну марнай, хвалячыся сваёй шчодрасцю. 2:264
- Шайтан (Сатана) пагражае вам галечай і загадвае вам учыняць паскудствы (дрэнныя ўчынкі, незаконныя палавыя зносіны, грахі). 2:268
- Шукайце тых, хто мае патрэбу, і дапамагайце ім. 2:273
- Не ўдзельнічайце ў ліхвярстве і працэнтах. Не спажывайце маёмасці, якая прыносіць працэнты. Не яжце рыбу (ліхву). 2:275
- Дайце больш часу на пагашэнне, калі пазычальнік знаходзіцца ў цяжкім становішчы. 2:280
- Трымайце слова ў дзелавых аперацыях. Будзьце праўдзівымі ў фінансавых справах. Дзейнічайце сумленна ва ўсіх абавязацельствах. Калі вы заключаеце дагавор пазыкі на пэўны тэрмін, запісвайце яго. Бярыце сведкаў, калі заключаеце камерцыйны кантракт. 2:282
- Захоўвайце і выконвайце ўсе даверы. 2:283
- Верце ў Ніспасланыя Кнігі і ва ўсіх Прарокаў. 2:285
- Алах не ўскладае на душу больш, чым яна можа вынесці. Яна атрымае ўзнагароду за набытае ёю дабро і пакаранне за набытае ёю зло. Бог не ўскладае на чалавека больш, чым ён можа вынесці; і мы не павінны рабіць гэтага. Спадзявайцеся на план Алаха нават у цяжкасцях. 2:286
- Хто выконвае запаветы і баіцца Алаха, таго Алах любіць. 3:76
- Здзейсніце хадж (паломніцтва), калі маеце магчымасць. 3:97
- Не раз'ядноўвайцеся. 3:103
- Загадвайце дабро і забараняйце зло. Заахвочвайце справядлівасць у вашай супольнасці. Заклікайце іншых да памінання Алаха. 3:104
- На Алаха павінны спадзявацца вернікі. 3:122
- Не яжце рыбу (ліхву). 3:130
- Падпарадкоўвайцеся Алаху і Яго Пасланцу, каб атрымаць міласць. 3:132
- Алах любіць тых, хто выдаткаў (на справу Алаха — міласціну, ахвяраванні і г.д.) у дастатку і ў нястачы, хто стрымлівае гнеў і хто даруе людзям. 3:134
- Стрымлівайце гнеў. Кантралюйце свой гнеў. 3:134
- Даруйце і прабачайце памылкі іншых. 3:135
- Не будзьце грубымі ў размове. Будзьце цярплівымі да тых, хто адрозніваецца ад вас. 3:159
- Калі Алах дапаможа вам, ніхто не зможа перамагчы вас; а калі Ён пакіне вас, то хто пасля Яго зможа дапамагчы вам? 3:160
- Кожны зведае смерць. І толькі ў Дзень Уваскрэсення вам будзе выплачана поўная ўзнагарода. 3:185
- Глыбока задумайцеся пра цуды прыроды і стварэнне гэтага сусвету. Ведайце, што Бог стварыў сусвет са сэнсам і мэтай. 3:191
- Мужчыны і жанчыны маюць роўныя ўзнагароды за свае ўчынкі. 3:195
- Для тых, хто баіцца свайго Госпада, ёсць сады, пад якімі цякуць рэкі (у Раі); яны будуць там вечна, як гасціннасць ад Алаха. 3:198
- Заўсёды імкніцеся да задавальнення Алаха ў кожным дзеянні. 3:200
- Будзьце пабожнымі перад Госпадам вашым, бойцеся Яго і (не разарывайце) сувязі (роднасці). 4:1
- Аддавайце сіротам іх маёмасць і не абменьвайце (сваё дрэннае) на іх (добрае); і не паглынайце іх маёмасць (далучаючы да сваёй). 4:2
- Давайце жанчынам (на якіх вы жэніцеся) іх махр (абавязковы шлюбны дар, які муж дае жонцы ў час шлюбу) з добрым сэрцам. 4:4
- Ахоўвайце правы сірот. 4:6
- Маёмасць памерлага павінна быць размеркавана сярод членаў яго сям'і. Жанчыны маюць права на спадчыну. 4:7
- Не спажывайце маёмасці сірот несправядліва. 4:10
- Выконвайце запаведзі адносна спадчыны. 4:11
- Забаронена атрымліваць у спадчыну жанчын супраць іх волі і абыходзіцца з імі жорстка. Жывіце з імі (жонкамі) з годнасцю. Паважайце і захоўвайце правы жанчын. Абыходзьцеся з вашай жонкай з дабрынёй і спачуваннем. Абыходзьцеся з жанчынамі з гонарам і справядлівасцю. 4:19
- Не ажаніцеся з тымі, хто звязаны з вамі крывёю. 4:23
- Не забівайце адзін аднаго. Сапраўды, Алах міласэрны да вас. Не спажывайце маёмасці адзін аднаго несправядліва. 4:29
- Калі вы пазбягаеце вялікіх грахоў, якія забаронены, Алах даруе вам (малыя) грахі і ўвядзе вас у высакародны ўваход (г. зн. Рай). 4:31
- Не жадайце таго, у чым Алах даў перавагу адным з вас перад другімі. Пазбягайце зайздрасці і раўнівасці. 4:32
- Мужчыны з'яўляюцца ахоўнікамі і апекунамі жанчын, таму што Алах аддаў перавагу адных перад другімі, і таму што яны выдаткаў (на іх утрыманне) са сваіх сродкаў. Мужчына з'яўляецца ахоўнікам і апекуном сям'і. 4:34
- Пакланяйцеся Алаху і не далучайце да Яго нікога ў пакланенні, рабіце дабро бацькам, сваякам, сіротам, бедным, суседу, таварышу, які побач з вамі, падарожніку (якога вы сустракаеце) і тым (нявольнікам), якімі валодаюць вашыя правыя рукі. Алах не любіць тых, хто ганарысты і хвалькаваты. Будзьце добрымі да іншых. Праяўляйце міласэрнасць да слабых. Падтрымлівайце сямейныя сувязі і паважайце сваякоў. 4:36
- Не будзьце скнарамі. 4:37
- Алах не даруе, калі Яму далучаюць супольнікаў, але даруе, што менш за гэта, каму пажадае. 4:48
- Не зайздросціце іншым. 4:54
- Алах загадвае вам вяртаць даверы тым, каму яны належаць. Калі вы судзіце паміж людзьмі, судзіце справядліва. 4:58
- Падпарадкоўвайцеся Алаху і Яго Пасланцу. Выяўляйце належную павагу да тых, хто мае ўладу сярод вас. 4:59
- Не ўціскайце слабых і ўразлівых. 4:75
- Што б ні прыйшло да вас добрага, гэта ад Алаха, а што б ні здарылася з вамі дрэннага, гэта ад саміх вас. 4:79
- Хто падпарадкоўваецца Пасланцу (Мухамаду, хай мір яму і блаславенне), той ужо падпарадкаваўся Алаху. 4:80
- Хто заступніцца за добрую справу, той атрымае долю ўзнагароды за яе; а хто заступніцца за дрэнную справу, той атрымае долю пакарання за яе. 4:85
- Не належыць верніку забіваць верніка, акрамя як памылкова. 4:92
- Хто заб'е верніка наўмысна, таму адплатай будзе Геена, дзе ён будзе вечна. Гнеў і праклён Алаха будуць на ім, і для яго падрыхтавана вялікае пакаранне. 4:93
- Хто перасяляецца (са свайго дома) на шляху Алаха, той знойдзе на зямлі шмат прытулкаў і багацця. 4:100
- Будзьце пунктуальныя ў вашых малітвах. 4:103
- Не падтрымлівайце і не будзьце абаронцамі тых, хто здраджвае даверам. 4:105
- Шукайце прабачэння Алаха, сапраўды, Алах — прабачальны, міласэрны. 4:106
- Вы, тыя, хто ўвераваў! Будзьце цвёрдымі ў справядлівасці, сведачачы перад Алахам, нават калі гэта супраць вас саміх, або вашых бацькоў, або вашых сваякоў, багаты ён ці бедны. Не адкладайце справядлівасць; дзейнічайце неадкладна, каб выправіць памылкі. 4:135
- Гіпакрыты хочуць абдурыць Алаха, але Ён абдурвае іх. 4:142
- Гіпакрыты будуць у самым ніжнім (узроўні) Агню; і не знойдзеце вы для іх памочніка. 4:145
- Алах не любіць, каб зло прамаўлялася ўголас, акрамя тых, хто быў скрыўджаны. 4:148
- Пасланцы як веснікі добрай весткі і як папярэднікі, каб пасля Пасланцоў у людзей не было справы супраць Алаха. 4:165
- Выконвайце вашыя дагаворы і абяцанні. 5:1
- Дапамагайце адзін аднаму ў дабрыні і пабожнасці, але не ў граху і варожасці. 5:2
- Не ешце мерцвячыну, кроў жывёл і свініну. 5:3
- Будзьце справядлівымі, няхай варожасць і нянавісць да іншых не адхіляе вас ад справядлівасці. Будзьце справядлівымі. Ведайце, што справядлівасць блізкая да пабожнасці. Не адкладайце справядлівасць; дзейнічайце неадкладна, каб выправіць памылкі. 5:8
- Шукайце сродкі набліжэння да Алаха і змагайцеся на Яго шляху, як толькі можаце. Каб вы дабіліся поспеху. 5:35
- Выконвайце вашыя клятвы і запаветы. 5:89
- Пазбягайце ап'яняльных напояў і алкаголю. Строга пазбягайце ап'яняльных напояў (усе віды алкагольных напояў), азартных гульняў, аль-ансаб (каменных ахвярнікаў) і аль-азлям (стрэл для пошуку ўдачы або рашэння), якія з'яўляюцца паскудствам дзеянняў Шайтана. 5:90
- Не забівайце дзічыну, калі вы знаходзіцеся ў стане іхрама для хаджу або ўмры (паломніцтва). 5:95
- Не пытайцеся пра рэчы, якія, калі іх вам растлумачаць, могуць вас засмуціць. 5:101
- Не зневажайце багоў іншых. Не зневажайце тых, каму яны (няверныя) пакланяюцца акрамя Алаха, каб яны не сталі зневажаць Алаха па няведанні. 6:108
- Калі вы будзеце падпарадкоўвацца большасці тых, хто на зямлі, яны ўвядуць вас у зман, збіўшы з шляху Алаха. Яны прытрымліваюцца толькі здагадак і толькі хлусяць. 6:116
- Пакіньце (людзі) усялякі грэх, відавочны і схаваны. 6:120
- Не ешце (вернікі) з таго (мяса), над якім не было вымаўлена імя Алаха (у час забойства жывёлы). 6:121
- Каго Алах хоча наставіць на прамы шлях, таму Ён раскрывае грудзі для Ісламу; а каго Ён хоча збіць з шляху, таму Ён робіць грудзі вузкімі і сціснутымі. 6:125
- Будзьце ўмеранымі ў выдаткаванні і пазбягайце марнатраўства. Захоўвайце правы ўсіх стварэнняў. 6:141
- Не далучайце нічога да Алаха ў пакланенні, будзьце добрымі і паслухмянымі да бацькоў, не забівайце сваіх дзяцей з-за беднасці, не набліжайцеся да паскудных учынкаў, не забівайце нікога, каго Алах забараніў, акрамя як па праве. 6:151
- Будзьце сумленнымі; не падманвайце ні ў якіх вашых справах. Не набліжайцеся да маёмасці сіраты, акрамя як з мэтай палепшыць яе, давайце поўную меру і поўную вагу па справядлівасці, калі даяце слова, кажыце праўду, нават калі гэта датычыць блізкага сваяка, і выконвайце Запавет Алаха. 6:152
- Ідзіце па Простаму Шляху і не ідзіце (іншымі) шляхамі, бо яны аддзеляць вас ад Яго Шляху. 6:153
- Скажы (Мухамад): "Сапраўды, мая малітва, мая ахвяра, маё жыццё і мая смерць — для Алаха, Госпада сусветаў." 6:162
- Не будзьце ганарыстымі. 7:13
- Няхай Шайтан (Сатана) не падмане вас. 7:27
- Скажы (Мухамад): "Мой Гасподзь загадаў справядлівасць…" 7:29
- Прытрымлівайцеся межаў, устаноўленых Алахам, ва ўсіх пытаннях. Пазбягайце празмернасцей у словах і дзеяннях. Ешце і піце, але не празмернічайце. Насіце прыгожую вопратку падчас малітваў. 7:31
- Алах стварыў нябёсы і зямлю за шэсць дзён, а потым узвысіўся на Троне (сапраўдным чынам, годным Яго Вялікасці). 7:54
- Звяртайцеся да вашага Госпада з пакорлівасцю і ўтаймавана. Ён не любіць тых, хто пераступае межы. 7:55
- І не чыніце бязладдзя на зямлі пасля таго, як яна прыведзена ў парадак, і звяртайцеся да Яго з боязню і надзеяй. 7:56
- А тыя, хто здзейсніў злыя ўчынкі, а потым пакаяліся і ўверавалі, — сапраўды, твой Гасподзь пасля гэтага прабачальны, міласэрны. 7:153
- Скажы (Мухамад): "Людзі! Я — Пасланец Алаха да вас усіх." 7:158
- І (усе) Найпрыгажэйшыя Імёны належаць Алаху, таму звяртайцеся да Яго па іх і пакіньце тых, хто зневажае Яго Імёны… 7:180
- Каго Алах зводзіць з шляху, таму няма настаўніка; і Ён пакідае іх блукаць у іх празмернасцях. 7:186
- Праяўляйце паблажлівасць, загадвайце дабро і пазбягайце невукаў (г. зн. не карайце іх). 7:199
- Даруйце іншым іх памылкі. 7:199
- І калі шэпт ад Шайтана (Сатаны) кранецца цябе, то шукай сховішча ў Алаха. Сапраўды, Ён — Чуючы, Ведаючы. 7:200
- Вернікі — гэта тыя, у каго, калі згадваецца Алах, узнікае страх у сэрцах, і калі ім чытаюць Яго аяты, яны павялічваюць сваю веру. 8:2
- Не здраджвайце Алаху і Яго Пасланцу і не здраджвайце свядома вашым даверам (і ўсім абавязкам, якія Алах усклаў на вас). 8:27
- Калі вы будзеце падпарадкоўвацца і баяцца Алаха, Ён дасць вам Фуркан (крытэрый (каб адрозніваць праўду ад хлусні), або (выхад, каб вывесці вас з любых цяжкасцей)). 8:29
- Тыя, хто не верыць, выдаткаваюць сваё багацце, каб адхіліць (людзей) ад шляху Алаха, і яны будуць працягваць выдаткаваць яго; але ў рэшце рэшт гэта стане для іх пакутай. 8:36
- Скажы тым, хто не ўвераваў, калі яны спыняцца (ад нявер'я), ім будзе даравана тое, што было раней. Але калі яны вернуцца (да нявер'я), то прыклады тых (хто быў пакараны) раней ужо былі (як папярэджанне). 8:38
- Калі вы сустрэнеце (варожую) сілу, стойце цвёрда і часта ўзгадвайце імя Алаха (мовай і розумам), каб дасягнуць поспеху. 8:45
- Не будзьце падобныя да тых, хто выходзіў са сваіх дамоў з ганарыстасцю і каб паказаць сябе людзям, і (таксама) адхілялі (людзей) ад шляху Алаха. 8:47
- Алах ніколі не змяняе ласкі, якую Ён дараваў людзям, пакуль яны не зменяць тое, што ў іх саміх. 8:53
- Найгоршымі з жывых стварэнняў перад Алахам з'яўляюцца тыя, хто не верыць. 8:55
- Бог укладвае любоў і прыхільнасць паміж сэрцамі тых, хто верыць у Яго. 8:63
- Абараняйце і дапамагайце тым, хто шукае абароны. 9:6
- Не належыць шматбожнікам утрымліваць мячэці Алаха. 9:17
- Яны (няверныя, іўдзеі і хрысціяне) хочуць патушыць святло Алаха (з якім быў пасланы Мухамад — ісламскі адзінабожжа) сваімі вуснамі, але Алах не дазволіць, каб Яго святло не было дасканалым, нават калі няверныя гэтага ненавідзяць. 9:32
- Садакат (г.зн. закят) прызначаюцца толькі: 1) бедным, 2) небагатым, 3) тым, хто збірае іх, 4) для тых, чыі сэрцы схіляюцца да Ісламу, 5) для вызвалення палонных, 6) для тых, хто пагрузіўся ў доўг, 7) для тых, хто на шляху Алаха (для змагароў), і 8) для падарожнікаў. 9:60
- Хто працівіцца і праяўляе варожасць да Алаха і Яго Пасланца (хай мір яму і блаславенне), таму будзе Агонь Геены, дзе ён будзе вечна. Гэта вялікая ганьба. 9:63
- Гіпакрыты, мужчыны і жанчыны, падобныя адзін да аднаго. Яны забылі Алаха, і Ён забыў іх. 9:67
- Імкніцеся да чысціні. Паважайце святасць мячэці. 9:108
- Не належыць (Прароку і вернікам) прасіць прабачэння для шматбожнікаў, нават калі яны сваякі, пасля таго як ім стала відавочна, што яны будуць насельнікамі Агню (таму што яны памерлі ў нявер'і). 9:113
- Хто больш несправядлівы, чым той, хто ўзводзіць на Алаха хлусню або адхіляе Яго аяты? Сапраўды, грэшнікі не будуць мець поспеху! 10:17
- Яны пакланяюцца акрамя Алаха таму, што не шкодзіць ім і не прыносіць карысці, і кажуць: "Яны — нашы заступнікі перад Алахам." Скажы: "Ці паведамляеце вы Алаху пра тое, чаго Ён не ведае на нябёсах і на зямлі?" Хвала Ён і Ён вышэй за тое, што яны далучаюць да Яго! 10:18
- Уздаяненнем за зло з'яўляецца такое ж зло. 10:27
- Такі Алах, ваш сапраўдны Гасподзь. Што ж пасля праўды, акрамя зману? Як жа вы адвярнуліся? 10:32
- Большасць з іх прытрымліваецца толькі здагадак. Сапраўды, здагадкі нічога не вартыя перад праўдай. 10:36
- Сапраўды! Алах не ўціскае людзей ні ў чым; але людзі самі сябе ўціскаюць. 10:44
- Ведайце, што ласка Божая лепшая за ўсё, што чалавек можа назапасіць або назапашваць. 10:58
- Не будзьце аднымі з тых, хто адхіляе аяты Алаха, бо тады вы апынецеся сярод тых, хто нясе страты. 10:95
- Калі Алах кране цябе шкодай, ніхто не зможа адхіліць яе, акрамя Яго; а калі Ён жадае табе дабра, ніхто не зможа спыніць Яго ласку, якую Ён даруе таму з Яго рабоў, каму пажадае. 10:107
- Няма на зямлі ніводнай жывой істоты, якая б не атрымлівала ежу ад Алаха. І Ён ведае яе месца знаходжання і месца захавання (у чэраве, магіле і г.д.). 11:6
- Калі мы даем чалавеку пакаштаваць ласку ад Нас, а потым адбіраем яе, ён прыходзіць у роспач і становіцца няўдзячным. 11:9
- Хто жадае зямнога жыцця і яго пацеры, тым Мы дамо поўную ўзнагароду за іх учынкі і не паменшым іх. 11:15
- Мы не былі несправядлівыя да іх, але яны самі былі несправядлівыя да сябе. І багі іх, акрамя Алаха, да якіх яны звярталіся, не дапамаглі ім, калі прыйшоў загад твайго Госпада, і толькі павялічылі іх пагібель. 11:101
- У той дзень, калі ён настане, ніхто не прамовіць без Яго (Алаха) дазволу. Сярод іх будуць і няшчасныя, і (іншыя) шчаслівыя. 11:105
- Што тычыцца тых, хто няшчасны, яны будуць у Агні, стогнучы і галосячы. 11:106
- Яны будуць там вечна, пакуль існуюць нябёсы і зямля, акрамя таго, што захоча твой Гасподзь. Сапраўды, твой Гасподзь робіць тое, што хоча. 11:107
- А тыя, хто шчаслівы, будуць у Раі, дзе будуць вечна, пакуль існуюць нябёсы і зямля, акрамя таго, што захоча твой Гасподзь, у якасці дару, які не будзе спынены. 11:108
- Не схіляйцеся да тых, хто чыніць несправядлівасць, каб вас не крануў Агонь, і не будзе ў вас абаронцаў, акрамя Алаха, і тады вам не дапамогуць. 11:113
- Выконвайце салят на двух канцах дня і ў начныя гадзіны (г. зн. 5 штодзённых малітваў). Добрыя справы змываюць дрэнныя (г. зн. малыя грахі). 11:114
- Алаху належыць схаванае на нябёсах і на зямлі, і да Яго вяртаюцца ўсе справы (для вырашэння). 11:123
- Загад (ці рашэнне) належыць толькі Алаху. Ён загадаў, каб вы пакланяліся толькі Яму (адзінабожжа), гэта правільная рэлігія, але большасць людзей не ведае. 12:40
- Ніколі не трацьце надзею на міласць Алаха. 12:87
- І большасць людзей не ўверуе, нават калі вы гэтага вельмі жадаеце. 12:103
- І большасць з іх не верыць у Алаха, не далучаючы да Яго супольнікаў (г. зн. яны шматбожнікі). 12:106
- Гэта (Каран) не звычайнае слова, а пацверджанне таго, што было да яго (Таўрат, Евангелле і іншыя Пісанні), і падрабязнае тлумачэнне ўсяго, кіраўніцтва і міласць для тых, хто верыць. 12:111
- Алах павялічвае долю таму, каму хоча, і абмяжоўвае (каму хоча). 13:26
- Часта ўзгадвайце Алаха (праз зікр). Тыя, хто верыць у Бога, знаходзяць суцяшэнне ў памінанні Яго. 13:28
- Тыя, хто верыць і робіць дабро, атрымліваюць радасць і спакой душы. 13:29
- Тыя, хто аддае перавагу зямному жыццю перад будучым, і адхіляе (людзей) ад шляху Алаха (Ісламу) і імкнецца скрывіць яго, — яны знаходзяцца ў глыбокім змане. 14:3
- Праяўляйце пакорлівасць і ўдзячнасць у пакланенні. 14:7
- Прытча пра тых, хто адмаўляе свайго Госпада, падобная да попелу, над якім моцна дзьме вецер у бурны дзень; яны не змогуць атрымаць нічога з таго, што здабылі. 14:18
- Алах умацуе тых, хто ўвераваў, моцным словам у гэтым свеце (г. зн. яны будуць працягваць пакланяцца толькі Алаху) і ў будучым жыцці. 14:27
- Не думайце, што Алах не ведае пра тое, што чыняць бязбожнікі (шматбожнікі, крыўдзіцелі і г.д.), але Ён дае ім адтэрміноўку да Дня, калі вочы будуць глядзець у жаху. 14:42
- Каб Алах адплаціў кожнай душы за тое, што яна здабыла. Сапраўды, Алах хуткі ў разліку. 14:51
- І сапраўды, Мы стварылі чалавека з гліны, якая гучыць, з чорнага глею, які змяніўся. 15:26
- А джынаў Мы стварылі раней з полымя агню без дыму. 15:27
- Яго (Пекла) мае сем варот, для кожных варот прызначаны (асобны) клас грэшнікаў. 15:44
- Ён стварыў чалавека з вады (змяшанай кроплі мужчынскага і жаночага выдзялення), а потым ён становіцца адкрытым праціўнікам. 16:4
- І жывёлу Ён стварыў для вас; у іх ёсць цяпло (цёплая вопратка) і шмат карысці, і вы імі харчуецеся. 16:5
- (І стварыў) коней, мулаў і аслоў для язды і ўпрыгожання. І Ён стварае тое, чаго вы не ведаеце. 16:8
- Ён той, хто высылае з неба ваду (дождж); з яе вы п'яце, і дзякуючы ёй расце трава, якой вы пасвіце жывёлу. 16:10
- Ён — Той, Хто падпарадкаваў вам мора, каб вы елі з яго свежае мяса (рыбу) і даставалі з яго ўпрыгожанні, якія вы носіце. 16:14
- Ён усталяваў на зямлі непахісныя горы, каб яна не вагалася разам з вамі, і рэкі, і дарогі, каб вы знайшлі праўдзівы шлях. 16:15
- Ці ж Той, Хто стварае, падобны да таго, хто не стварае? Няўжо вы не памятаеце? 16:17
- Калі вы паспрабуеце палічыць ласкі Алаха, вам не ўдасца іх палічыць. 16:18
- Алах ведае тое, што вы ўтойваеце, і тое, што вы абвяшчаеце. 16:19
- Тыя, каго яны (шматбожнікі) клічуць акрамя Алаха, не стварылі нічога, але самі створаны. 16:20
- (Яны) мёртвыя, без жыцця, і не ведаюць, калі будуць уваскрэшаны. 16:21
- Наша слова для таго, калі Мы чагосьці зажадаем, гэта сказаць яму: "Стань!" — і яно становіцца. 16:40
- Няўжо тыя, хто будуе падступныя планы, адчуваюць сябе ў бяспецы ад таго, што Алах не пагоніць іх у зямлю, або што пакаранне не прыйдзе да іх з таго боку, адкуль яны не чакаюць? 16:45
- Усе даброты і ласкі, якія вы маеце, — ад Алаха. Калі ж вас кране няшчасце, вы голасна клічаце Яго на дапамогу. 16:53
- А калі Ён адхіляе ад вас няшчасце, дык вось тады некаторыя з вас далучаюць да свайго Госпада супольнікаў. 16:54
- У жывёле ёсць для вас урок. Мы даем вам піць з таго, што знаходзіцца ў іх жыватах — сумесь пераваранай ежы і крыві — чыстае малако, прыемнае для тых, хто яго п'е. 16:66
- Такім чынам, не давайце Алаху падобных (бо нічога падобнага да Яго няма, і Ён не падобны ні на што). Сапраўды, Алах ведае, а вы не ведаеце. 16:74
- Ведайце, што Бог даў людзям слых, зрок, інтэлект і пачуцці, каб яны былі ўдзячныя. 16:78
- Пазбягайце прагнасці і сквапнасці. 16:97
- Калі вы хочаце чытаць Каран, шукайце сховішча ў Алаха ад Шайтана (Сатаны), прагнанага (праклятага). 16:98
- Ведайце, што зло, учыненае па няведанні, даруецца, калі чалавек пакаецца і выправіцца. 16:119
- Заклікай (Мухамад) да шляху твайго Госпада (Ісламу) з мудрасцю і добрым настаўленнем і вядзі з імі размову найлепшым чынам. Заклік іншых да шляху Бога павінен быць з мудрасцю і дабрынёю. 16:125
- Алах з тымі, хто баіцца Яго (выконвае свой абавязак перад Ім), і з тымі, хто робіць дабро. 16:128
- Гэты Каран вядзе да таго, што з'яўляецца найболей правільным і справядлівым. 17:9
- Ніхто не можа несці цяжар грахоў іншага. 17:15
- Хто жадае будучага жыцця і імкнецца да яго з належным імкненнем, будучы вернікам, — вось тыя, чыё імкненне будзе адзначана і ўзнагароджана (Алахам). 17:19
- Шануйце сваіх бацькоў і абыходзьцеся з імі дабрынёй. Будзьце паслухмяныя да бацькоў. Не гаварыце ім ніводнага слова непавагі. І твой Гасподзь загадаў вам пакланяцца толькі Яму. І быць добрым да бацькоў. Калі адзін з іх ці абодва дасягнуць старасці, не кажыце ім "Цьфу!", не крычыце на іх, а кажыце з імі пачціва. 17:23
- І схілі перад імі крыло пакоры з міласэрнасці і скажы: "Госпадзе мой! Злітуйся над імі, як яны выхоўвалі мяне ў дзяцінстве." 17:24
- Сапраўды, марнатраўцы — браты шатанаў, а Шайтан няўдзячны свайму Госпаду. 17:27
- Не марнуйце грошы. 17:29
- Не забівайце сваіх дзяцей з-за страху беднасці. 17:31
- Не ўчыняйце пералюбу. Захоўвайце святасць шлюбу і пазбягайце пералюбу. 17:32
- Давайце поўную меру, калі адмяраеце, і важце на правільнай шалі. Гэта лепш (карысней) і лепш у выніку. 17:35
- Не ідзі (чалавек) за тым, пра што ты не маеш ведаў (напрыклад, калі хтосьці кажа: "Я бачыў", хоць насамрэч не бачыў, або "Я чуў", хоць не чуў). 17:36
- Будзьце пакорнымі і не будзьце ганарыстымі. Не хадзіце па зямлі з пагардай. Сапраўды, вы не можаце разрэзаць (прабіць) зямлю і не можаце дасягнуць вышыні гор. 17:37
- Ваш Гасподзь лепш за ўсіх ведае вас; калі Ён захоча, змілуецца над вамі, або калі захоча, пакарае вас. 17:54
- Хто быў сляпым у гэтым свеце (г. зн. не бачыць знакаў Алаха і не верыць у Яго), будзе сляпым у будучым жыцці і яшчэ больш збітым з шляху. 17:72
- Выконвайце прадпісаныя малітвы ў іх час. 17:78
- Мы ўсебакова растлумачылі людзям у гэтым Каране ўсялякія прытчы, але большасць людзей адмаўляецца ад праўды, акрамя нявер'я. 17:89
- Мы прывялі ў гэтым Каране любыя прыклады для людзей. Але чалавек больш за ўсё схільны да спрэчак. 18:54
- Іх узнагародай будзе Пекла; таму што яны не верылі і насміхаліся з Маіх аятаў і Маіх Пасланцоў. 18:106
- Не падобае (Велічы) Алаха мець дзіця (гэта нагадвае пра паклёп хрысціян на Алаха, якія кажуць, што Ісус з'яўляецца сынам Алаха). Хвала Яму! 19:35
- Гаварыце з людзьмі ветліва. 20:44
- Спаборнічайце адзін з адным у здзяйсненні дабра. 21:90
- Пазбягайце пустаслоўя. 23:3
- Захоўвайце сваю цнатлівасць. 23:5
- Беражыце сваё сэрца ад грахоўных схільнасцей. 23:97
- Даруйце іншым і прабачайце іх правіны. 24:22
- Паважайце прыватнае жыццё іншых, асабліва ў іх дамах. Выконвайце правы суседзяў. 24:27
- Апусціце позірк (як для мужчын, так і для жанчын). Захоўвайце сваю цнатлівасць і маральную чысціню. 24:30
- Захоўвайце сціпласць у вопратцы і паводзінах. 24:31
- Ведайце, што Бог дае бяспеку і спакой тым, хто пакланяецца Яму і чыніць дабро. 24:55
- Не ўваходзьце ў пакой бацькоў без дазволу. 24:58
- Будзьце сціплымі і пакорнымі. 25:63
- Пазбягайце ілжывага сведчання і падману. 25:72
- Імкніцеся да ўзнагароды ў будучым жыцці, але не грэбуйце сваімі справамі ў гэтым свеце. 28:77
- Не звяртайцеся да іншага боства, акрамя Алаха. 28:88
- Не ўступайце ў гомасексуальныя адносіны. 29:29
- Імкніцеся да дасканаласці ва ўсіх вашых пачынаннях. 29:69
- Выконвайце малітву і давайце міласціну. 31:4
- Загадвайце дабро і забараняйце зло. 31:17
- Пазбягайце ганарыстасці ў паводзінах. Не марнуйце час у пустых размовах. 31:18
- Будзьце ўмеранымі ў хаду і ў гучнасці вашага голасу. 31:19
- Ідзіце па прыкладзе Прарока Мухамада. 33:21
- Жанчыны не павінны выстаўляць або хваліцца сваёй прыгажосцю і ўпрыгожаннямі. 33:33
- Гаварыце праўду ва ўсіх абставінах. 33:70
- Шукайце мудрасці і разумення праз роздум. 38:29
- Выконвайце запаведзі Карана. 39:23
- Бог даруе ўсе грахі, калі грэшнік каецца і звяртаецца да Яго. 39:53
- Звяртайцеся да Алаха з шчырай дуа (мальбой). 40:60
- Адхіляйце зло тым, што лепш. 41:34
- Вырашайце справы пасродкам кансультацый. 42:38
- Не падымайце свой голас вышэй за голас Прарока. 49:2
- Захоўвайце сакрэты і пазбягайце здрады. 49:6
- Садзейнічайце міру паміж тымі, хто знаходзіцца ў канфлікце. Імкніцеся да прымірэння ў канфліктах. 49:9
- Не высмейвайце іншых. 49:11
- Пазбягайце падазрэнняў. Пазбягайце шпіянажу і пляткарання. Не пляткарыце і не ганьбіце іншых. Устрымлівайцеся ад усіх формаў пляткарання і паклёпу. Не дазваляйце ганарыстасці весці вас да несправядлівасці. 49:12
- Ведайце, што толькі набожнасць робіць чалавека высакародным. Паважайце адрозненні паміж людзьмі і культурамі. 49:13
- Паважайце гасцей. 51:26
- Будзьце ўважлівымі да вашых абавязкаў перад Алахам. 51:56
- Выдаткоўвайце маёмасць на міласціну. 57:7
- Ведайце, што ў рэлігіі няма манаства (адмова ад шлюбу і зручнасцей, як у манахаў, манашак або іншых, якія жывуць пад рэлігійнымі абяцаннямі, або будынкаў, у якіх яны жывуць). 57:27
- Няхай багацце не адцягвае вас ад памінання Алаха. 58:11
- Тыя, хто мае веды, атрымаюць больш высокі статус ад Бога. 58:11
- Абыходзьцеся з немусульманамі па-добраму і справядліва. 60:8
- Пазбягайце крывадушнасці ў вашых перакананнях і ўчынках. 63:9
- Трымайцеся далей ад прагнасці і сквапнасці. 64:16
- Захоўвайце адкрыцці, давераныя вам. 73:15
- Памятайце пра Дзень Судны. 75:36
- Загадвайце цярпенне і спачуванне. 90:17
- Тыя, хто ачышчае свае душы, дасягаюць поспеху, а тыя, хто апаганьвае іх, церпяць няўдачу. 91:10
- Не праганяйце тых, хто мае патрэбу. 93:10
- Імкніцеся да ведаў і разумення. Чытайце і разважайце над Кананом. 96:1–5
- Заахвочвайце карміць бедных. 107:3
